import numpy as np
from scipy import sparse
from scipy.sparse.linalg._eigen.arpack import arpack as _ap
from scipy.sparse._sparsetools import csr_matvec

try:
    from threadpoolctl import threadpool_limits
except Exception:
    threadpool_limits = None


class Solver:
    def solve(self, problem, **kwargs):
        A = problem["matrix"]
        k = problem["k"]
        if threadpool_limits is not None:
            with threadpool_limits(limits=1, user_api="blas"):
                return self._solve(A, k)
        return self._solve(A, k)

    def _solve(self, A, k):
        A = sparse.csr_matrix(A)
        n = A.shape[0]
        tp = A.dtype.char
        if tp != 'd':
            return self._fallback(A, k)
        v0 = np.ones(n, dtype=A.dtype)
        ncv = max(2 * k + 1, 20)
        params = _ap._UnsymmetricArpackParams(
            n, k, tp, None and None or (lambda x: A @ x), 1, None, None, None,
            ncv, v0, n * 200, "LM", 0)
        solver = params._arpack_solver
        d = params.arpack_dict
        resid, v, ipntr, workd, workl = params.resid, params.v, params.ipntr, params.workd, params.workl
        indptr, indices, data = A.indptr, A.indices, A.data
        while True:
            solver(d, resid, v, ipntr, workd, workl)
            ido = d['ido']
            if ido == 1 or ido == 5:
                x0 = ipntr[0]; y0 = ipntr[1]
                y = workd[y0:y0 + n]
                y[:] = 0.0
                csr_matvec(n, n, indptr, indices, data, workd[x0:x0 + n], y)
            elif ido == 2:
                x0 = ipntr[0]; y0 = ipntr[1]
                workd[y0:y0 + n] = workd[x0:x0 + n]
            elif ido == 99 or ido not in (3, 4):
                if d['info'] == 0:
                    break
                return self._fallback(A, k)
            else:
                return self._fallback(A, k)
        vals, vecs = params.extract(True)
        order = sorted(range(len(vals)), key=lambda i: -np.abs(vals[i]))
        return [vecs[:, i] for i in order]

    def _fallback(self, A, k):
        N = A.shape[0]
        v0 = np.ones(N, dtype=A.dtype)
        w, V = sparse.linalg.eigs(A, k=k, v0=v0, maxiter=N * 200, ncv=max(2 * k + 1, 20))
        pairs = list(zip(w, V.T))
        pairs.sort(key=lambda p: -np.abs(p[0]))
        return [p[1] for p in pairs]

